			hint = [=[Atenda ao apelo que vem de um cristal nas montanhas do norte.]=],
			text = [=[Um fragmento pulsou na mão, e veio a visão de um cristal nas montanhas do norte. Ali a voz disse seu nome: Myzrael, presa nas profundezas por gigantes. Ela pediu ajuda, e pediu com gentileza.]=],
