Translate("ptBR", "thoradin", {
	title = "Thoradin",
	subtitle = "Primeiro Rei de Arathor",
	allegiance = "A tribo Arathi · Arathor",
	sections = {
		{
			title = "Resumo",
			text = [=[Thoradin foi o senhor da guerra da tribo {link:arathi-highlands}Arathi{/link} que fez da humanidade uma nação. Numa era em que as tribos humanas do norte lutavam entre si enquanto os trolls caçavam todas elas, ele as uniu sob um só estandarte. Deu ao novo reino o nome de {link:arathor}Arathor{/link} e ergueu sua capital, {link:stromgarde-keep}Strom{/link}, no planalto que leva o nome de sua tribo. Todos os reinos humanos dos dias de hoje descendem de sua obra.]=],
		},
		{
			title = "Importância",
			text = [=[Antes de Thoradin havia tribos. Depois dele havia um povo. Sua aliança com os elfos venceu as {link:troll-wars}Guerras Trolls{/link} e trouxe o conhecimento da magia à humanidade, e sua linhagem foi honrada pelos elfos de {link:quel-thalas}Quel'Thalas{/link} por milhares de anos. A grande muralha entre o planalto e {link:hillsbrad-foothills}Eira dos Montes{/link} ainda leva seu nome.]=],
		},
		{
			title = "A União das Tribos",
			text = [=[Os {link:arathi-highlands}Arathi{/link} combatiam os Amani havia mais tempo que qualquer outra tribo, e Thoradin aprendera a guerra na fronteira dos trolls. Ele viu o que os outros chefes não queriam ver: que os trolls destruiriam as tribos uma a uma. Uniu-as por todos os meios que tinha. Algumas ganhou pelo casamento, outras com promessas de terras e riquezas, e outras derrotou em batalha. Os que derrotou, não humilhou. Fez de seus chefes seus generais, e assim eles se tornaram seus homens mais leais.]=],
		},
		{
			title = "Strom",
			text = [=[Thoradin estabeleceu sua capital nas planícies secas do planalto, longe das florestas densas onde os trolls armavam suas emboscadas. A fortaleza de {link:stromgarde-keep}Strom{/link} tornou-se um lugar de refúgio, e humanos vieram até ela de todo o continente. Aqui também a humanidade aprendeu pela primeira vez as artes arcanas.]=],
		},
		{
			title = "As Guerras Trolls",
			text = [=[Quando os Amani caíram sobre {link:quel-thalas}Quel'Thalas{/link}, os elfos enviaram emissários a {link:stromgarde-keep}Strom{/link}. Prometeram ensinar os caminhos da magia a cem humanos em troca das espadas de {link:arathor}Arathor{/link}. Thoradin aceitou. Sua hoste atacou os trolls no sul das terras élficas e os atraiu para o sopé das {link:alterac-mountains}Montanhas de Alterac{/link}, onde os elfos e os novos magos humanos caíram sobre eles pelo outro lado. Os Amani foram quebrados. Em gratidão, os elfos juraram amizade à linhagem de Thoradin.]=],
		},
		{
			title = "O Legado",
			text = [=[Thoradin desejava que {link:stromgarde-keep}Strom{/link} continuasse sendo o coração de seu reino, e temia um império espalhado demais. Depois dele, seu povo partiu mesmo assim e fundou {link:dalaran}Dalaran{/link}, {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiraz{/link}, {link:alterac-mountains}Alterac{/link} e Lordaeron. Strom declinou. Por fim, os últimos de sua linhagem a deixaram e navegaram para o sul para fundar um novo reino. Muitos séculos depois, {link:anduin-lothar}Anduin Lothar{/link}, o último dessa linhagem, liderou a {link:alliance}Aliança{/link} de {link:lordaeron}Lordaeron{/link} na {link:second-war}Segunda Guerra{/link}.]=],
		},
		{
			title = "Não Registrado",
			text = [=[As histórias pouco dizem da própria família de Thoradin, de seus últimos anos ou de sua morte. Este registro não faz suposições sobre eles.]=],
		},
	},
	chapters = {
		{
			title = "O Sigilo de Thoradin",
			hint = "Siga o sigilo quebrado que leva o nome do primeiro rei.",
			text = [=[Entre os selos que guardam a tumba dos Trollbane há um sigilo com o nome de Thoradin. O Príncipe {link:prince-galen-trollbane}Galen{/link} o quebrou e espalhou seus pedaços entre seus últimos defensores. Os pedaços foram tirados de seus corpos, e um xamã troll da {link:horde}Horda{/link} os uniu inteiros de novo. O nome do primeiro rei tornara-se uma chave nas mãos dos trolls que seu povo um dia derrotou.]=],
		},
	},
	mentions = {
		{ text = "O Sigilo Quebrado" },
		{ text = "Sigilo de Thoradin" },
	},
	bonds = {
		{ id = "arathor", name = "Arathor", note = "a nação que ele fundou" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "o último de sua linhagem" },
		{ id = "thoradin-s-wall", name = "Muralha de Thoradin", note = "leva seu nome" },
		{ id = "stromgarde-keep", name = "Bastilha de Stromgarde", note = "outrora sua capital, Strom" },
	},
})

