		{
			title = "Resumo",
			text = [=[Thoras Trollbane foi o rei de {link:stromgarde-keep}Stromgarde{/link}, herdeiro da antiga casa que governa a cidade desde que a linhagem real de {link:arathor}Arathor{/link} a deixou. Foi um rei guerreiro numa terra de soldados duros. Agora está morto, e seu reino morreu com ele. Jaz numa tumba selada n'O Sacrário, atrás da capela de Stromgarde, com a espada de sua casa a seu lado.]=],
		},
		{
			title = "Importância",
			text = [=[Thoras foi um dos governantes que ergueram a {link:alliance}Aliança{/link} de {link:lordaeron}Lordaeron{/link} contra a {link:horde}Horda{/link}. Sua casa descende de Ignaeus, o general das {link:troll-wars}Guerras Trolls{/link} cuja lâmina {link:trol-kalar}Trol'kalar{/link} deu à família seu nome. Para os trolls de {link:azeroth}Azeroth{/link}, o nome Trollbane ainda é uma maldição.]=],
		},
		{
			title = "Feitos",
			text = [=[• Levou {link:stromgarde-keep}Stromgarde{/link} para a {link:alliance}Aliança de Lordaeron{/link} na {link:second-war}Segunda Guerra{/link}.
• Depois da guerra, quando a Aliança discutia os {link:internment-camps}campos de internação{/link} e seu custo, retirou Stromgarde dela.
• Foi sepultado com {link:trol-kalar}Trol'kalar{/link}, a espada de Ignaeus.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica destes dias registra como Thoras Trollbane morreu. Seu povo diz apenas que ele se foi.]=],
		},
	},
	chapters = {
		{
			title = "A Tumba n'O Sacrário",
			hint = "Fique diante da tumba do último rei de Stromgarde.",
			text = [=[A tumba do Rei Thoras fica atrás da capela do bairro dos defensores, vigiada por zeladores da casa. Sua face é entalhada com linhas que nenhuma mão pode abrir sem os sigilos que seu filho espalhou. Nas mãos de pedra sobre a tumba jaz {link:trol-kalar}Trol'kalar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Trollbane, a notícia de sua morte" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "Príncipe Galen Trollbane", note = "seu filho" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "seu aliado na Aliança" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "a espada de sua casa" },
	},
})

Translate("ptBR", "trol-kalar", {
	title = "Trol'kalar",
	sections = {
		{
			title = "Resumo",
			text = [=[Trol'kalar é a antiga espada da casa Trollbane. Seu nome significa matadora de trolls na língua dos próprios trolls. Foi empunhada nas guerras de {link:arathor}Arathor{/link} por Lorde Ignaeus de {link:stromgarde-keep}Strom{/link}, o inimigo mais temido que os trolls já enfrentaram, e deu à sua casa o nome que ela leva.]=],
		},
		{
			title = "A Tumba",
			text = [=[Quando o {link:thoras-trollbane}Rei Thoras{/link} morreu, Trol'kalar foi depositada em sua tumba n'O Sacrário, atrás da capela de {link:stromgarde-keep}Stromgarde{/link}, presa nas mãos de pedra. A tumba foi selada com proteções que só respondem a um sigilo. O Príncipe {link:prince-galen-trollbane}Galen{/link} dividiu esse sigilo em quatro: o Sigilo de Strom, o Sigilo de {link:thoradin}Thoradin{/link}, o Sigilo de {link:arathor}Arathor{/link} e o Sigilo de Trollbane. Um caiu nas mãos da {link:syndicate}Camarilha{/link} junto com a cidade. Os outros ele deu a seus soldados, a seu líder de cavalaria e a si mesmo. Reunidos, os quatro se tornam um só, o Sigilo de Ignaeus.]=],
		},
		{
			title = "O Presente",
			text = [=[{link:vol-jin}Vol'jin{/link}, dos {link:darkspear-trolls}Lançanegra{/link}, quer a espada. Ele enviou o caçador {link:zengu}Zengu{/link} a {link:hammerfall}Ruína do Martelo{/link} para tomá-la, para que a matadora de trolls de {link:stromgarde-keep}Strom{/link} possa ser voltada contra os trolls Gurubashi de {link:zul-gurub}Zul'Gurub{/link}.]=],
		},
	},
})

Translate("ptBR", "witherbark-trolls", {
	title = "Trolls Cascasseca",
	aliases = { "Cascasseca", "trolls Cascasseca", "tribo Cascasseca" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Cascasseca são uma tribo de {link:trolls}trolls{/link} da floresta que vive no sudeste do {link:arathi-highlands}Planalto Arathi{/link}. Sua aldeia fica entre as colinas dali, com cavernas atrás onde se reúnem seus líderes de bando. Os trolls combatem os humanos de {link:stromgarde-keep}Strom{/link} desde os dias de {link:thoradin}Thoradin{/link}, e os Cascasseca ainda guardam essa guerra junto ao coração.]=],
		},
		{
			title = "Seus Costumes",
			text = [=[A tribo tem arremessadores de machado, caçadores de cabeças, berserkers e curandeiros que carregam bolsas de remédios e amuletos de pedra-de-sangue. Seus caçadores das sombras recebem uma faca especial quando completam os ritos de sua passagem. Dois líderes de bando, Zalas Witherbark e Nimar, o Matador, os levam à guerra.]=],
		},
		{
			title = "O Presente",
			text = [=[Os Cascasseca um dia lutaram ao lado dos orcs, e depois os deixaram. Agora se uniram aos {link:boulderfist-ogres}ogros Punho de Pedra{/link} para expulsar a {link:horde}Horda{/link} de {link:hammerfall}Ruína do Martelo{/link}. Seus combatentes dividem o monte de ogros de {link:boulder-gor}Pedre'gor{/link}, e berserkers da tribo estão ao lado dos ogros nas ruínas de {link:stromgarde-keep}Stromgarde{/link}. {link:drum-fel}Drum Fel{/link}, de Ruína do Martelo, fez deles o primeiro alvo de sua guerra.]=],
		},
	},
})

Translate("ptBR", "boulderfist-ogres", {
	title = "Ogros Punho de Pedra",
	aliases = { "Punho de Pedra", "ogros Punho de Pedra", "clã Punho de Pedra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Punho de Pedra são o maior clã de {link:ogres}ogros{/link} do {link:arathi-highlands}Planalto Arathi{/link}. Eles ocupam o monte de {link:boulder-gor}Pedre'gor{/link}, as cavernas do {link:boulderfist-hall}Forte Punho de Pedra{/link} e grande parte da cidade arruinada de {link:stromgarde-keep}Stromgarde{/link}. Nenhuma crônica registra quando chegaram ao planalto.]=],
		},
		{
			title = "Seus Costumes",
			text = [=[São brutos, executores, espancadores e senhores, com magos e xamãs que aprenderam a usar os tesouros que saqueiam. Seus xamãs dão grande valor às ágatas azuis tomadas da Torre de {link:arathor}Arathor{/link}. No {link:boulderfist-hall}Forte Punho de Pedra{/link}, o {link:ogres}ogro{/link} mago {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link} lança gelo com uma varinha roubada. Em {link:stromgarde-keep}Stromgarde{/link}, o ogro {link:or-kalar}Or'Kalar{/link} os comanda em nome de {link:mug-thol}Mug'thol{/link}, um senhor da guerra que não é do planalto.]=],
		},
		{
			title = "O Presente",
			text = [=[Os Punho de Pedra combatem os soldados de {link:stromgarde-keep}Stromgarde{/link} e a {link:syndicate}Camarilha{/link} pelas ruínas da cidade, e se uniram aos {link:witherbark-trolls}trolls Cascasseca{/link} contra {link:hammerfall}Ruína do Martelo{/link}. Kovork, Molok, o Esmagador, {link:ruul-eagletalon}Ruul{/link} Onestone e Foulbelly são temidos entre seus chefes.]=],
		},
	},
})

Translate("ptBR", "drywhisker-kobolds", {
	title = "Kobolds Drywhisker",
	aliases = { "Drywhisker", "kobolds Drywhisker" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Drywhisker são uma tribo de {link:kobolds}kobolds{/link} que escava na {link:drywhisker-gorge}Garganta Seca{/link}, no extremo nordeste do planalto. São agrimensores e escavadores, e entre eles trabalha um geomante chamado Flintdagger, que comanda o fogo.]=],
		},
		{
			title = "Os Fragmentos",
			text = [=[Os Drywhisker não são apenas mineiros. No fundo de sua garganta, guardam um aglomerado de fragmentos de cristal iridescentes, e carregam consigo partículas de um poder estranho. O ser que jaz preso sob o planalto os chama de aliados dos gigantes que a mantêm cativa. Três deles andam ao lado do próprio vigia de pedra {link:fozruk}Fozruk{/link}. Ninguém sabe o que os gigantes deram aos kobolds por seus serviços, nem se os kobolds sequer entendem a quem servem.]=],
		},
	},
})

Translate("ptBR", "league-of-arathor", {
	title = "Liga de Arathor",
	sections = {
		{
			title = "Resumo",
			text = [=[A Liga de Arathor é a força combatente do que resta do reino de {link:stromgarde-keep}Stromgarde{/link}. Seus soldados são herdeiros de um reino orgulhoso cuja capital está agora nas mãos de ogros e bandidos. Eles juraram reconquistar o planalto para o povo de Stromgarde e para a {link:alliance}Aliança{/link}.]=],
		},
		{
			title = "Sua Causa",
			text = [=[A Liga acampa na {link:refuge-pointe}Ponta do Refúgio{/link} sob o comando do {link:field-marshal-oslight}Marechal de Campo Oslight{/link}. Sua primeira batalha é pela {link:arathi-basin}Bacia Arathi{/link}, um vale fértil de fazendas, minas, forjas e florestas. A Liga pretende reivindicar as riquezas da bacia para seus aliados em {link:stormwind-city}Ventobravo{/link}, e através de Ventobravo para toda a {link:alliance}Aliança{/link}. Seus soldados ocupam o Salão dos Matatroll, na borda do vale, cujo nome vem da casa real de {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "O Presente",
			text = [=[A Liga enfrenta os {link:defilers}Profanadores Renegados{/link} na bacia. Seu oficial de suprimentos, Samuel Hawke, envia provisões aos que lutam, e seus sargentos exortam cada soldado a atacar antes que o inimigo o faça.]=],
		},
	},
})

Translate("ptBR", "defilers", {
	title = "Profanadores",
	aliases = { "Os Profanadores", "Profanadores Renegados" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Profanadores são tropas de elite dos {link:forsaken}Renegados{/link}, enviadas ao {link:arathi-highlands}Planalto Arathi{/link} sob o olhar atento de {link:varimathras}Varimathras{/link}. Eles combatem a {link:league-of-arathor}Liga de Arathor{/link} pela {link:arathi-basin}Bacia Arathi{/link}. Seu propósito não é a guerra dos orcs, mas a de sua própria rainha: isolar os humanos do norte de seus aliados anões do sul, e tomar as riquezas da bacia para a {link:undercity}Cidade Baixa{/link}.]=],
		},
		{
			title = "Seu Acampamento",
			text = [=[Os Profanadores mantêm seu quartel-general em {link:hammerfall}Ruína do Martelo{/link}, ao lado dos orcs e trolls do posto avançado, sob o comando do {link:deathmaster-dwire}Mestre da Morte Dwire{/link}. Na bacia, ocupam o Covil do Profanador. Seu oficial de suprimentos, Rutherford Twing, envia provisões aos que lutam por eles, e o Sicário Mortis serve ao lado de Dwire.]=],
		},
		{
			title = "O Presente",
			text = [=[{link:deathmaster-dwire}Dwire{/link} acredita que até o pequeno acampamento da {link:refuge-pointe}Ponta do Refúgio{/link} poderia um dia ameaçar a {link:horde}Horda{/link}. Os Profanadores pretendem garantir que {link:arathi-highlands}Arathi{/link} jamais volte a ser um lar para humanos.]=],
		},
	},
})
